	'dashboard.tour.step_menu_forever_products_text' => 'Ovde se otvaraju sadržaji i članci o proizvodima koje možeš da podeliš uz svoju preporuku. To je važan deo podsticanja interesovanja i usmeravanja posetilaca ka Forever internet prodavnici.',
	'dashboard.tour.step_menu_blog_title' => 'Blog',
	'dashboard.tour.step_menu_blog_text' => 'Blog ti nudi širi izbor obrazovnih i poslovnih sadržaja koje možeš da koristiš u objavama i porukama i za izgradnju poverenja putem korisnog sadržaja, a ne samo direktnom prodajom.',
	'dashboard.tour.step_menu_contact_title' => 'Kontakt',
	'dashboard.tour.step_menu_contact_text' => 'Ovde su dostupni kontakt i podrška za dodatna pitanja. Kada nešto nije jasno ili ti je potrebno usmerenje, ovo je jedno od mesta na kojima možeš da zatražiš pomoć.',
	'dashboard.tour.step_menu_dashboard_title' => 'Idi na kontrolnu tablu',
	'dashboard.tour.step_menu_dashboard_text' => 'Kontrolna tabla je tvoj komandni centar. Ovde pratiš svoj signal, učiš uz vodiče, vidiš šta funkcioniše i odlučuješ koji će biti tvoj sledeći korak.',
	'dashboard.tour.step_hero_title' => 'Početna stranica tvog FCC rada',
	'dashboard.tour.step_hero_text' => 'Ovaj gornji odeljak prikazuje gde si trenutno, na šta se usredsređuješ i koji su ti najbrži putevi do aplikacija, podrške i edukativnih vodiča.',
	'dashboard.tour.step_growth_title' => 'Signali i otključavanja',
	'dashboard.tour.step_growth_text' => 'Ovde možeš da vidiš koliko stvarne aktivnosti vodi ka Forever Living internet prodavnici preko tvoje FCC aplikacije, bloga i drugih alata. Taj signal utiče na tempo AI pomoći i sledeće mogućnosti koje se otključavaju u tvom planu rasta.',
	'dashboard.tour.step_tutorials_title' => 'Kratki tutorijali i edukacija',
	'dashboard.tour.step_tutorials_text' => 'Ovde otvaraš kratke praktične vodiče za određene radnje. Tako FCC edukacija izgleda u praksi: ne samo kroz teoriju, već i kroz male korake koje možeš odmah da primeniš.',
	'dashboard.tour.step_workbench_title' => 'Radni prostor',
	'dashboard.tour.step_workbench_text' => 'Ovde odmah vidiš šta funkcioniše, gde se gubi rezultat i koji delovi sistema već privlače interesovanje. To ti pomaže da donosiš odluke na osnovu stvarnih signala, a ne nagađanja.',
	'dashboard.tour.step_chart_title' => 'Klikovi koji donose rezultate',
	'dashboard.tour.step_chart_text' => 'Grafikon razdvaja aplikaciju → Forever, blog → Forever, registracije i kontakte od levka i AI četa, kako bi jasno video/la koji deo sistema stvara stvarni poslovni signal.',
	'dashboard.tour.step_next_action_title' => 'Tvoj sledeći korak',
	'dashboard.tour.step_next_action_text' => 'Ovaj blok ti daje jednu jasnu preporuku šta da uradiš sada. Cilj FCC-a nije da te zatrpa podacima, već da ti pomogne da izabereš najkorisniji sledeći korak.',
	'dashboard.tour.step_support_title' => 'Podrška i teme vebinara',
	'dashboard.tour.step_support_text' => 'Ovde možeš da otvoriš podršku, pročitaš odgovore administratora i predložiš teme za vebinare kojima želiš da se posvetimo. To je deo FCC edukacije, koja ti pomaže kada zapneš ili želiš bolje razumevanje.',
