	'qr_codes.subheader' => 'Lako kreiraj prilagodljive QR kodove i sačuvaj ih za kasniju upotrebu.',
	'qr_codes.page_intro' => 'Napravi zasebne QR kodove za štampu, deljenje van mreže, događaje, proizvode, WiFi, razmenu kontakata i mnoge druge namene. Svaka aplikacija Forever Card može da napravi i sopstveni direktni QR kod, a ovaj odeljak ti pruža zaseban prostor za QR kodove u kom možeš da ih praviš i uređuješ na jednom mestu.',
	'qr_codes.guide_title' => 'Poseban QR radni prostor za štampu, deljenje van mreže i kontrolisane načine korišćenja',
	'qr_codes.guide_text' => 'Ovaj QR odeljak namenjen je samostalnim QR materijalima kojima želiš da upravljaš van određenog ekrana aplikacije. Koristi ga kada su ti potrebni QR kodovi za štampu, kodovi kampanja za ponovnu upotrebu, pristupne tačke za događaje ili proizvode, ili QR kod kome su potrebni zaseban izgled i postupak izvoza.',
	'qr_codes.guide_card_1_title' => 'Odvojeno od QR koda aplikacije',
	'qr_codes.guide_card_1_text' => 'Svaka Forever Card App može da generiše sopstveni direktni QR kod, ali ovde možeš da kreiraš potpuno odvojene QR kodove za druge odredišne stranice, linkove, materijale i kampanje.',
	'qr_codes.guide_card_2_title' => 'Namenjeno štampanju i korišćenju bez interneta',
	'qr_codes.guide_card_2_text' => 'Ovi QR kodovi su idealni za letke, vizitkarte, postere, listove o proizvodima, stolove na događajima, ambalažu i deljenje uživo, kada ljudi skeniraju kod umesto da nešto kucaju.',
	'qr_codes.guide_card_3_title' => 'Prilagodi i pravilno izvezi',
	'qr_codes.guide_card_3_text' => 'Upravljaj vrstom QR koda, stilom, bojama, okvirima, logotipom, brendiranjem i izlaznim formatom datoteke kako bi konačni kod odgovarao mestu na kom će se koristiti.',
	'qr_codes.guide_card_4_title' => 'Uredi i ponovo upotrebi kasnije',
	'qr_codes.guide_card_4_text' => 'Kada se napravi, svaki QR kod ostaje dostupan za preuzimanje, štampanje, umnožavanje i kasnije dorade, bez potrebe da ga praviš ispočetka.',
	'qr_codes.empty_title' => 'Napravi svoj prvi QR kod',
	'qr_codes.empty_text' => 'Počni sa samostalnim QR kodom za link, aplikaciju, kontakt, događaj ili štampani materijal. Nakon kreiranja možeš da se vratiš i izmeniš stil, okvir, brendiranje i format izvoza.',
	'qr_codes.tour.create_title' => 'Napravi samostalan QR kod',
	'qr_codes.tour.create_text' => 'Koristi ovo dugme kada želiš QR kod koji nije vezan za jednu stranicu aplikacije Forever Card. Idealan je za kampanje, štampane materijale, događaje i deljenje van mreže koje možeš ponovo da koristiš.',
	'qr_codes.tour.guide_title' => 'Saznaj kada je ovo odeljak pravo mesto',
	'qr_codes.tour.guide_text' => 'Ovaj vodič objašnjava razliku između QR kodova namenjenih određenim aplikacijama i samostalnih QR elemenata. Cilj je da pomogne korisnicima da izaberu odgovarajući postupak pre kreiranja ili uređivanja.',
	'qr_codes.tour.list_title' => 'Tvoja QR biblioteka je ovde uredno organizovana',
