	'qr_codes.editor.hero_card_4_title' => 'Ponovo upotrebi umesto da praviš ispočetka',
	'qr_codes.editor.hero_card_4_text' => 'Kada QR kod dobro funkcioniše, nastavi da ga uređuješ, umnožavaš ili izvoziš za nove kampanje, umesto da svaki put počinješ ispočetka.',
	'qr_codes.editor.tour.intro_title' => 'Pregled QR uređivača',
	'qr_codes.editor.tour.intro_text' => 'Ova stranica ti pomaže da napraviš ili doradiš samostalni QR kôd koji možeš da odštampaš, podeliš, izvezeš i ponovo koristiš u različitim situacijama.',
	'qr_codes.editor.tour.type_title' => 'Izaberi šta skeniranje treba da uradi',
	'qr_codes.editor.tour.type_text' => 'QR tip određuje šta će se desiti kada ga neko skenira: otvaranje linka, čuvanje kontakt podataka, pokretanje poruke, povezivanje na WiFi, prikaz zahteva za plaćanje i drugo.',
	'qr_codes.editor.tour.basics_title' => 'Počni od imena i glavnih podataka',
	'qr_codes.editor.tour.basics_text' => 'Daj QR kodu jasno interno ime i popuni osnovna polja sa sadržajem. Ovo je glavni sadržaj koji će biti ugrađen u kod.',
