	'qr_codes.editor.tour.style_text' => 'Stil određuje oblik QR modula i uglova. Ovo je korisno kada QR treba vizuelno da se uklopi u brend, kampanju ili štampani materijal.',
	'qr_codes.editor.tour.colors_title' => 'Podesi kontrast i jasnoću skeniranja',
	'qr_codes.editor.tour.colors_text' => 'Boje nisu samo estetsko pitanje. Dobar kontrast je ključan za pouzdano skeniranje, naročito kada će QR kod biti odštampan ili se posmatrati pri lošem osvetljenju.',
	'qr_codes.editor.tour.frame_title' => 'Dodaj kontekst oko QR koda',
	'qr_codes.editor.tour.frame_text' => 'Okviri pomažu da QR kod izgleda osmišljeno i mogu da sadrže poziv na akciju ili oznaku, kako bi ljudi odmah razumeli zašto treba da ga skeniraju.',
	'qr_codes.editor.tour.branding_title' => 'Pažljivo dodaj logotip i slojeve brenda',
	'qr_codes.editor.tour.branding_text' => 'Opcije brendiranja omogućavaju da u QR kompoziciju postaviš logotipe i slike, ali treba ih pažljivo testirati kako bi se očuvala čitljivost.',
	'qr_codes.editor.tour.options_title' => 'Završi tehnička podešavanja',
