	'link.short_editor.hero_title' => 'Pretvori jednostavan kratak URL u kontrolisani tok preusmeravanja',
	'link.short_editor.hero_text' => 'U ovom uređivaču kratka veza postaje strateški alat. Osim nadimka i odredišta, možeš da dodaš zakazivanje, UTM praćenje, zaštitu lozinkom, povezivanje sa aplikacijom, maskiranje, usmeravanje prema uređaju ili lokaciji, HTTP ponašanje i druge napredne kontrole.',
	'link.short_editor.hero_card_1_title' => 'Počni od osnova',
