	'link.short_editor.card_1_title' => 'Za jednostavna lansiranja',
	'link.short_editor.card_1_text' => 'Podesi odredište, pseudonim, domen i kod za preusmeravanje kako bi veza radila tačno kako želiš već pri prvom deljenju.',
	'link.short_editor.card_2_title' => 'Za kampanje i izveštavanje',
