	'link.short_editor.tour.intro_text' => 'Ova stranica objedinjuje sve napredne opcije za jednu kratku vezu. Cilj je jednostavan: da pomogne ljudima da razumeju šta se menja svakim podešavanjem pre nego što sačuvaju izmene.',
	'link.short_editor.tour.basics_title' => 'Najpre osnove',
